create_order_flag.code:
import {orderFlags} from 'webcommander-sdk';

const response = await orderFlags.createOrderFlag(client, {
    order_flag: {name: 'Awaiting Stock', color: '#5A7BD4', description: 'Waiting for stock to arrive.'},
});
console.log(response.map.order_flag.id);

